export function getApricaWinterWeekNyeContent(locale: string): CapodannoLocalizedEventContent {
  return (
    (APRICA_CONTENT_35 as Record<string, CapodannoLocalizedEventContent | undefined>)[locale] ||
    APRICA_CONTENT_35.en
  );
}

export function getApricaSkuLocalized35(
  skuId: string,
  locale: string,
): { title: string; description: string } | null {
  const byLoc =
    (APRICA_SKU_COPY_35 as Record<string, Record<string, { title: string; description: string }> | undefined>)[locale] ||
    APRICA_SKU_COPY_35.en;
  return byLoc[skuId] || null;
}
